const replaceMergeTags = (value, preview) => {
  if (!preview || typeof value !== "string") return value;
  return value.replace(/\{\{([a-zA-Z0-9_]+)\}\}/g, (match, key) => sampleValues[key] || match);
};

const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

const createDesignerState = () => {
  if (typeof window === "undefined") {
    return { elements: defaultElements, settings: defaultSettings };
  }

  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (!saved) return { elements: defaultElements, settings: defaultSettings };
    const parsed = JSON.parse(saved);
    return {
      elements: Array.isArray(parsed.elements) ? parsed.elements : defaultElements,
      settings: parsed.settings || defaultSettings,
    };
  } catch {
    return { elements: defaultElements, settings: defaultSettings };
  }
};

