const renderElementContent = (element, preview) => {
  const content = replaceMergeTags(element.content, preview);

  if (element.type === "logo") {
    return (
      <Box sx={{ display: "flex", alignItems: "center", height: "100%", gap: 1.2 }}>
        <Box
          sx={{
            width: 62,
            height: 62,
            borderRadius: "50%",
            border: "7px solid #2e75c7",
            display: "grid",
            placeItems: "center",
            color: "#61c774",
            fontWeight: 900,
            fontSize: 26,
            lineHeight: 1,
          }}
        >
          {content}
        </Box>
        <Typography sx={{ color: alpha("#7acb95", 0.85), fontSize: 8, letterSpacing: 1, lineHeight: 1.1 }}>
          {replaceMergeTags(element.subtitle, preview)}
        </Typography>
      </Box>
    );
  }

  if (element.type === "headline") {
    const lines = String(content).split("\n");
    return (
      <Box sx={{ color: element.style.color, fontWeight: element.style.fontWeight, fontSize: element.style.fontSize, lineHeight: element.style.lineHeight }}>
        {lines.map((line, index) => {
          const isAccent = index >= lines.length - 2;
          return (
            <Box
              key={`${line}-${index}`}
              sx={{
                color: isAccent ? element.style.accentColor : "inherit",
                fontStyle: isAccent ? "italic" : "normal",
              }}
            >
              {line}
            </Box>
          );
        })}
      </Box>
    );
  }

  if (element.type === "metric") {
    return (
      <Box
        sx={{
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          borderTop: `1px solid ${alpha("#ffffff", 0.35)}`,
          color: "#fff",
        }}
      >
        <Typography sx={{ fontWeight: 900, fontSize: 18, lineHeight: 1 }}>
          {content}
          <Box component="span" sx={{ ml: 0.5, fontSize: 10, color: "#9ee0aa" }}>
            {replaceMergeTags(element.unit, preview)}
          </Box>
        </Typography>
        <Typography sx={{ mt: 1, color: alpha("#ffffff", 0.64), fontSize: 9, textTransform: "uppercase", letterSpacing: 1.6 }}>
          {replaceMergeTags(element.label, preview)}
        </Typography>
      </Box>
    );
  }

  return (
    <Typography
      sx={{
        color: element.style.color,
        fontSize: element.style.fontSize,
        fontWeight: element.style.fontWeight,
        lineHeight: element.style.lineHeight,
        letterSpacing: element.style.letterSpacing,
        textAlign: element.style.textAlign,
        whiteSpace: "pre-line",
      }}
    >
      {content}
    </Typography>
  );
};

