const QuoteDesigner = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const initialState = useMemo(() => createDesignerState(), []);
  const [view, setView] = useState("list");
  const [panel, setPanel] = useState("variables");
  const [elements, setElements] = useState(initialState.elements);
  const [settings, setSettings] = useState(initialState.settings);
  const [selectedId, setSelectedId] = useState("customer");
  const [preview, setPreview] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [device, setDevice] = useState("desktop");
  const [zoom, setZoom] = useState(isMobile ? 0.46 : 0.76);
  const [search, setSearch] = useState("");
  const [dragState, setDragState] = useState(null);
  const [notice, setNotice] = useState("");

  const selectedElement = useMemo(
    () => elements.find((element) => element.id === selectedId) || null,
    [elements, selectedId],
  );

  const filteredGroups = useMemo(() => {
    const term = search.trim().toLowerCase();
    if (!term) return variableGroups;
    return variableGroups
      .map((group) => ({
        ...group,
        tags: group.tags.filter(([label, value]) =>
          `${label} ${value}`.toLowerCase().includes(term),
        ),
      }))
      .filter((group) => group.tags.length > 0);
  }, [search]);

  useEffect(() => {
    if (!dragState) return undefined;

    const handleMove = (event) => {
      const dx = (event.clientX - dragState.startX) / zoom;
      const dy = (event.clientY - dragState.startY) / zoom;
      setElements((current) =>
        current.map((element) => {
          if (element.id !== dragState.id) return element;
          if (dragState.mode === "resize") {
            return {
              ...element,
              w: clamp(dragState.origin.w + dx, 60, PAGE_WIDTH - dragState.origin.x),
              h: clamp(dragState.origin.h + dy, 32, PAGE_HEIGHT - dragState.origin.y),
            };
          }

          return {
            ...element,
            x: clamp(dragState.origin.x + dx, 0, PAGE_WIDTH - element.w),
            y: clamp(dragState.origin.y + dy, 0, PAGE_HEIGHT - element.h),
          };
        }),
      );
    };

    const handleUp = () => setDragState(null);

    window.addEventListener("mousemove", handleMove);
    window.addEventListener("mouseup", handleUp);
    return () => {
      window.removeEventListener("mousemove", handleMove);
      window.removeEventListener("mouseup", handleUp);
    };
  }, [dragState, zoom]);

  const startMove = useCallback(
    (event, id) => {
      if (preview) return;
      event.preventDefault();
      event.stopPropagation();
      const origin = elements.find((element) => element.id === id);
      if (!origin) return;
      setSelectedId(id);
      setDragState({ id, mode: "move", startX: event.clientX, startY: event.clientY, origin });
    },
    [elements, preview],
  );

  const startResize = useCallback(
    (event, id) => {
      if (preview) return;
      event.preventDefault();
      event.stopPropagation();
      const origin = elements.find((element) => element.id === id);
      if (!origin) return;
      setSelectedId(id);
      setDragState({ id, mode: "resize", startX: event.clientX, startY: event.clientY, origin });
    },
    [elements, preview],
  );

  const updateSelected = (patch) => {
    if (!selectedElement) return;
    setElements((current) =>
      current.map((element) =>
        element.id === selectedElement.id
          ? {
              ...element,
              ...patch,
              style: patch.style ? { ...element.style, ...patch.style } : element.style,
            }
          : element,
      ),
    );
  };

  const addTextElement = (content = "New text") => {
    const id = `text-${Date.now()}`;
    setElements((current) => [
      ...current,
      {
        id,
        type: "text",
        x: 118,
        y: 382,
        w: 280,
        h: 70,
        content,
        style: {
          color: "#ffffff",
          fontSize: 22,
          fontWeight: 800,
          lineHeight: 1.25,
          letterSpacing: 0,
          textAlign: "left",
        },
      },
    ]);
    setSelectedId(id);
  };

  const duplicateSelected = () => {
    if (!selectedElement) return;
    const clone = {
      ...selectedElement,
      id: `${selectedElement.id}-${Date.now()}`,
      x: clamp(selectedElement.x + 26, 0, PAGE_WIDTH - selectedElement.w),
      y: clamp(selectedElement.y + 26, 0, PAGE_HEIGHT - selectedElement.h),
    };
    setElements((current) => [...current, clone]);
    setSelectedId(clone.id);
  };

  const deleteSelected = () => {
    if (!selectedElement) return;
    setElements((current) => current.filter((element) => element.id !== selectedElement.id));
    setSelectedId(null);
  };

  const saveTemplate = () => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ elements, settings }));
    setNotice("Quote template saved.");
  };

  const setDeviceZoom = (nextDevice) => {
    const zoomMap = { desktop: 0.76, tablet: 0.58, mobile: 0.4 };
    setDevice(nextDevice);
    setZoom(zoomMap[nextDevice]);
  };

  const scheduleTotal = settings.schedule.reduce(
    (total, item) => total + Number(item.value || 0),
    0,
  );

  const updateSetting = (key, value) => {
    setSettings((current) => ({ ...current, [key]: value }));
  };

  const updateSchedule = (id, key, value) => {
    setSettings((current) => ({
      ...current,
      schedule: current.schedule.map((item) => (item.id === id ? { ...item, [key]: value } : item)),
    }));
  };

  const addScheduleStep = () => {
    setSettings((current) => {
      const nextId = String.fromCharCode(65 + current.schedule.length);
      return {
        ...current,
        schedule: [...current.schedule, { id: nextId, label: "New Milestone", value: "0" }],
      };
    });
  };

  const removeScheduleStep = (id) => {
    setSettings((current) => ({
      ...current,
      schedule: current.schedule.filter((item) => item.id !== id),
    }));
  };

  const templateList = (
    <Box sx={{ width: "100%", minHeight: "calc(100vh - 112px)", bgcolor: "#ffffff", p: { xs: 2, md: 3 } }}>
      <Stack direction={{ xs: "column", sm: "row" }} justifyContent="space-between" gap={1} sx={{ mb: 3 }}>
        <Typography variant="h5" fontWeight={900} color="#0f172a">
          Quote Designer
        </Typography>
        <Stack direction="row" gap={1} alignItems="center">
          <Typography fontSize={14} color="#64748b">Quotes</Typography>
          <Typography fontSize={16} color="#94a3b8">/</Typography>
          <Typography fontSize={14} color="#0f172a">Quote Designer</Typography>
        </Stack>
      </Stack>

      <Paper
        elevation={0}
        sx={{
          p: { xs: 3, md: 4 },
          mb: 3,
          border: "1px solid #dbe4ef",
          borderRadius: 3,
          background: "linear-gradient(135deg, #f8fafc 0%, #eef8f2 100%)",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 3,
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight={900} color="#1e293b" sx={{ mb: 1 }}>
            Quote Template Designer
          </Typography>
          <Typography color="#64748b" sx={{ maxWidth: 660, lineHeight: 1.7 }}>
            Customize quote templates with a visual editor. Drag text and variable blocks,
            edit settings, preview sample data, and save the layout.
          </Typography>
        </Box>
        <Paper
          elevation={0}
          sx={{
            minWidth: 146,
            height: 100,
            borderRadius: 3,
            border: "1px solid #d7e6de",
            bgcolor: alpha("#ffffff", 0.55),
            display: { xs: "none", sm: "grid" },
            placeItems: "center",
          }}
        >
          <Box textAlign="center">
            <Typography fontSize={34} fontWeight={900} color="#1e293b">1</Typography>
            <Typography fontSize={12} letterSpacing={1.8} color="#64748b">TEMPLATES</Typography>
          </Box>
        </Paper>
      </Paper>

      <Paper
        elevation={0}
        sx={{
          width: { xs: "100%", sm: 500 },
          border: "1px solid #e2e8f0",
          borderRadius: 3,
          overflow: "hidden",
          boxShadow: "0 12px 28px rgba(15,23,42,0.06)",
        }}
      >
        <Box sx={{ height: 250, bgcolor: "#f8fafc", display: "grid", placeItems: "center", position: "relative" }}>
          <TemplateThumbnail />
          <Chip
            label="Default"
            size="small"
            sx={{
              position: "absolute",
              right: 12,
              top: 12,
              bgcolor: "#55b9a3",
              color: "#ffffff",
              fontWeight: 800,
            }}
          />
        </Box>
        <Box sx={{ p: 3 }}>
          <Typography fontWeight={900} color="#0f172a" sx={{ mb: 0.6 }}>
            Enterprise
          </Typography>
          <Typography color="#64748b" fontSize={14} sx={{ mb: 3 }}>
            Full-page branded design with infographic-style solar data visualization
          </Typography>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={2}>
            <Typography fontSize={13} color="#94a3b8">17 May 2026, 09:57 PM</Typography>
            <Button
              variant="contained"
              startIcon={<Edit />}
              onClick={() => setView("editor")}
              sx={{ bgcolor: "#1f2a44", "&:hover": { bgcolor: "#111827" } }}
            >
              Edit Design
            </Button>
          </Stack>
        </Box>
      </Paper>
    </Box>
  );

  const variablesPanel = (
    <Box>
      <Typography fontWeight={900} letterSpacing={3} color="#64748b" fontSize={14} sx={{ mb: 2 }}>
        MERGE TAGS
      </Typography>
      <TextField
        fullWidth
        size="small"
        placeholder="Search variables..."
        value={search}
        onChange={(event) => setSearch(event.target.value)}
        sx={{ mb: 2, "& .MuiOutlinedInput-root": { borderRadius: 2 } }}
      />
      <Stack gap={1.5}>
        {filteredGroups.map((group) => (
          <Paper key={group.title} elevation={0} sx={{ border: "1px solid #e2e8f0", borderRadius: 2, overflow: "hidden" }}>
            <Stack direction="row" alignItems="center" gap={1} sx={{ px: 2, py: 1.3, bgcolor: "#f8fafc" }}>
              <Box sx={{ color: PRIMARY, display: "flex" }}>{group.icon}</Box>
              <Typography fontWeight={900} color="#0f172a">{group.title}</Typography>
            </Stack>
            <Box sx={{ p: 1.4, display: "flex", flexWrap: "wrap", gap: 1 }}>
              {group.tags.map(([label, value]) => (
                <Chip
                  key={value}
                  label={label}
                  size="small"
                  onClick={() => addTextElement(value)}
                  onDelete={() => addTextElement(value)}
                  deleteIcon={<ContentCopy />}
                  sx={{
                    bgcolor: alpha(PRIMARY, 0.08),
                    color: PRIMARY,
                    border: `1px solid ${alpha(PRIMARY, 0.16)}`,
                    fontFamily: "monospace",
                    borderRadius: 1.5,
                    "& .MuiChip-deleteIcon": { color: alpha(PRIMARY, 0.6) },
                  }}
                />
              ))}
            </Box>
          </Paper>
        ))}
      </Stack>
    </Box>
  );

  const settingsPanel = (
    <Stack gap={2}>
      {selectedElement && (
        <Paper elevation={0} sx={{ border: "1px solid #e2e8f0", borderRadius: 2, p: 2 }}>
          <Typography fontWeight={900} color="#0f172a" sx={{ mb: 1.5 }}>
            Selected Element
          </Typography>
          <TextField
            label="Content"
            fullWidth
            multiline
            minRows={selectedElement.type === "headline" ? 4 : 2}
            value={selectedElement.content || ""}
            onChange={(event) => updateSelected({ content: event.target.value })}
            sx={{ mb: 1.5 }}
          />
          {selectedElement.type === "metric" && (
            <Stack direction="row" gap={1} sx={{ mb: 1.5 }}>
              <TextField
                label="Unit"
                value={selectedElement.unit || ""}
                onChange={(event) => updateSelected({ unit: event.target.value })}
                size="small"
              />
              <TextField
                label="Label"
                value={selectedElement.label || ""}
                onChange={(event) => updateSelected({ label: event.target.value })}
                size="small"
              />
            </Stack>
          )}
          <Stack direction="row" gap={1}>
            <TextField
              label="Font"
              type="number"
              size="small"
              value={selectedElement.style?.fontSize || 16}
              onChange={(event) => updateSelected({ style: { fontSize: Number(event.target.value) } })}
            />
            <TextField
              label="Color"
              type="color"
              size="small"
              value={selectedElement.style?.color || "#ffffff"}
              onChange={(event) => updateSelected({ style: { color: event.target.value } })}
              sx={{ width: 96 }}
            />
          </Stack>
        </Paper>
      )}

      <Paper elevation={0} sx={{ border: "1px solid #e2e8f0", borderRadius: 2, p: 2 }}>
        <Typography fontWeight={900} letterSpacing={2} color="#64748b" fontSize={14} sx={{ mb: 2 }}>
          QUOTE SETTINGS
        </Typography>
        <Stack gap={1.5}>
          <TextField label="Electricity Tariff (Rs/Unit)" value={settings.electricityTariff} onChange={(event) => updateSetting("electricityTariff", event.target.value)} />
          <TextField label="Tariff Escalation (%/Year)" value={settings.tariffEscalation} onChange={(event) => updateSetting("tariffEscalation", event.target.value)} />
          <TextField label="Panel Degradation (%/Year)" value={settings.panelDegradation} onChange={(event) => updateSetting("panelDegradation", event.target.value)} />
          <TextField label="Projection Years" value={settings.projectionYears} onChange={(event) => updateSetting("projectionYears", event.target.value)} />
        </Stack>
      </Paper>

      <Paper elevation={0} sx={{ border: "1px solid #e2e8f0", borderRadius: 2, overflow: "hidden" }}>
        <Stack direction="row" alignItems="center" gap={1} sx={{ px: 2, py: 1.5, bgcolor: "#f8fafc" }}>
          <Payments sx={{ color: PRIMARY }} />
          <Typography fontWeight={900}>Payment Schedule</Typography>
        </Stack>
        <Stack gap={1.2} sx={{ p: 2 }}>
          {settings.schedule.map((item) => (
            <Stack key={item.id} direction="row" alignItems="center" gap={1}>
              <Typography width={18} fontWeight={900} color={PRIMARY}>{item.id}</Typography>
              <TextField
                size="small"
                value={item.label}
                onChange={(event) => updateSchedule(item.id, "label", event.target.value)}
                sx={{ flex: 1 }}
              />
              <TextField
                size="small"
                value={item.value}
                onChange={(event) => updateSchedule(item.id, "value", event.target.value)}
                sx={{ width: 76 }}
              />
              <Typography color="#64748b">%</Typography>
              <IconButton size="small" onClick={() => removeScheduleStep(item.id)}>
                <Delete fontSize="small" />
              </IconButton>
            </Stack>
          ))}
          <Stack direction="row" justifyContent="space-between" alignItems="center">
            <Typography fontSize={14} color={scheduleTotal === 100 ? "#0f172a" : "#ef4444"}>
              Total: {scheduleTotal}%
            </Typography>
            <Button size="small" startIcon={<Add />} onClick={addScheduleStep}>
              Add Step
            </Button>
          </Stack>
        </Stack>
      </Paper>

      <Button variant="contained" startIcon={<Save />} onClick={saveTemplate} sx={{ bgcolor: "#4b5f9f", "&:hover": { bgcolor: "#33457f" } }}>
        Save Settings
      </Button>
    </Stack>
  );

  const editorView = (
    <Box sx={{ width: "100%", bgcolor: "#f3f6fb", minHeight: "calc(100vh - 112px)", overflow: "hidden" }}>
      <Paper
        elevation={0}
        sx={{
          position: "sticky",
          top: 0,
          zIndex: 30,
          borderRadius: 0,
          borderBottom: "1px solid #e2e8f0",
          px: { xs: 1, md: 2 },
          py: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 1,
          flexWrap: "wrap",
        }}
      >
        <Stack direction="row" alignItems="center" gap={1.5}>
          <Tooltip title="Back">
            <IconButton onClick={() => setView("list")} sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}>
              <ArrowBack />
            </IconButton>
          </Tooltip>
          <Typography variant="h6" fontWeight={900} color="#0f172a">
            Enterprise
          </Typography>
        </Stack>

        <Stack direction="row" alignItems="center" gap={1} flexWrap="wrap">
          <Tooltip title="Duplicate selected">
            <span>
              <IconButton disabled={!selectedElement} onClick={duplicateSelected} sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}>
                <ContentCopy fontSize="small" />
              </IconButton>
            </span>
          </Tooltip>
          <Tooltip title="Delete selected">
            <span>
              <IconButton disabled={!selectedElement} onClick={deleteSelected} sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}>
                <Delete fontSize="small" />
              </IconButton>
            </span>
          </Tooltip>
          <Divider orientation="vertical" flexItem />
          {[
            ["desktop", <DesktopWindows fontSize="small" />],
            ["tablet", <TabletMac fontSize="small" />],
            ["mobile", <PhoneIphone fontSize="small" />],
          ].map(([value, icon]) => (
            <IconButton
              key={value}
              onClick={() => setDeviceZoom(value)}
              sx={{
                border: "1px solid #e2e8f0",
                borderRadius: 2,
                color: device === value ? PRIMARY : "#334155",
                bgcolor: device === value ? alpha(PRIMARY, 0.1) : "#fff",
              }}
            >
              {icon}
            </IconButton>
          ))}
          <Divider orientation="vertical" flexItem />
          <Button
            variant={panel === "variables" ? "contained" : "outlined"}
            startIcon={<Code />}
            onClick={() => setPanel("variables")}
          >
            Variables
          </Button>
          <Button
            variant={panel === "settings" ? "contained" : "outlined"}
            startIcon={<Settings />}
            onClick={() => setPanel("settings")}
          >
            Settings
          </Button>
        </Stack>

        <Stack direction="row" gap={1}>
          <Button
            variant="outlined"
            startIcon={<Visibility />}
            onClick={() => {
              setPreview(true);
              setPreviewOpen(true);
            }}
          >
            Preview
          </Button>
          <Button variant="contained" startIcon={<Save />} onClick={saveTemplate} sx={{ bgcolor: "#55b9a3", "&:hover": { bgcolor: "#379884" } }}>
            Save
          </Button>
        </Stack>
      </Paper>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: { xs: "1fr", lg: "360px minmax(0, 1fr)" },
          minHeight: "calc(100vh - 168px)",
        }}
      >
        <Box
          sx={{
            bgcolor: "#ffffff",
            borderRight: { lg: "1px solid #e2e8f0" },
            borderBottom: { xs: "1px solid #e2e8f0", lg: "none" },
            p: 2,
            maxHeight: { xs: "none", lg: "calc(100vh - 168px)" },
            overflowY: "auto",
          }}
        >
          {panel === "variables" ? variablesPanel : settingsPanel}
        </Box>

        <Box
          sx={{
            minWidth: 0,
            bgcolor: "#eef2f8",
            p: { xs: 2, md: 4 },
            overflow: "auto",
          }}
        >
          <Stack direction="row" justifyContent="center" gap={1} sx={{ mb: 2 }}>
            <Tooltip title="Zoom out">
              <IconButton onClick={() => setZoom((current) => clamp(Number((current - 0.08).toFixed(2)), 0.32, 1))}>
                <ZoomOut />
              </IconButton>
            </Tooltip>
            <Chip label={`${Math.round(zoom * 100)}%`} sx={{ fontWeight: 900, bgcolor: "#fff" }} />
            <Tooltip title="Zoom in">
              <IconButton onClick={() => setZoom((current) => clamp(Number((current + 0.08).toFixed(2)), 0.32, 1))}>
                <ZoomIn />
              </IconButton>
            </Tooltip>
            <Button size="small" variant={preview ? "contained" : "outlined"} onClick={() => setPreview((current) => !current)}>
              {preview ? "Editing Data" : "Show Sample Data"}
            </Button>
          </Stack>
          <Box sx={{ display: "flex", justifyContent: "center", minWidth: PAGE_WIDTH * zoom }}>
            <Box sx={{ width: PAGE_WIDTH * zoom, height: PAGE_HEIGHT * zoom, flexShrink: 0 }}>
              <Box sx={{ transform: `scale(${zoom})`, transformOrigin: "top left" }}>
                <QuotePage
                  elements={elements}
                  selectedId={selectedId}
                  preview={preview}
                  onSelect={setSelectedId}
                  onStartMove={startMove}
                  onStartResize={startResize}
                />
              </Box>
            </Box>
          </Box>
        </Box>
      </Box>
    </Box>
  );

  return (
    <>
      {view === "list" ? templateList : editorView}
      <Dialog
        open={previewOpen}
        onClose={() => {
          setPreviewOpen(false);
          setPreview(false);
        }}
        fullWidth
        maxWidth="lg"
      >
        <DialogTitle>Quote Preview</DialogTitle>
        <DialogContent dividers sx={{ bgcolor: "#eef2f8", overflow: "auto" }}>
          <Box sx={{ display: "flex", justifyContent: "center", minWidth: PAGE_WIDTH * 0.58 }}>
            <Box sx={{ width: PAGE_WIDTH * 0.58, height: PAGE_HEIGHT * 0.58 }}>
              <Box sx={{ transform: "scale(0.58)", transformOrigin: "top left" }}>
                <QuotePage
                  elements={elements}
                  selectedId={null}
                  preview
                  onSelect={() => {}}
                  onStartMove={() => {}}
                  onStartResize={() => {}}
                />
              </Box>
            </Box>
          </Box>
        </DialogContent>
      </Dialog>
      <Snackbar open={Boolean(notice)} autoHideDuration={2200} onClose={() => setNotice("")}>
        <Alert severity="success" sx={{ width: "100%" }}>
          {notice}
        </Alert>
      </Snackbar>
    </>
  );
};

export default QuoteDesigner;
